import { Button as BaseButton } from '@base-ui/react/button';
import type { ComponentType, ReactNode, Ref } from 'react';
import { cn } from '../../utils/cn';
import { rtlIconClass } from '../../utils/rtl';
import { Spinner } from '../spinner/Spinner';
import { buttonVariants, BUTTON_ICON_SIZE, type ButtonVariantProps } from './button.variants';

type IconComponent = ComponentType<{ size?: number; 'aria-hidden'?: boolean; className?: string }>;

export interface ButtonProps extends Omit<BaseButton.Props, 'className'>, ButtonVariantProps {
  className?: string;
  ref?: Ref<HTMLButtonElement>;
  /** Leading icon (a lucide icon component). Directional ones (ChevronLeft, ArrowRight…) mirror under RTL. */
  icon?: IconComponent;
  /** Trailing icon. */
  trailingIcon?: IconComponent;
  /** Shows a spinner, disables the button and sets aria-busy. */
  loading?: boolean;
  children?: ReactNode;
}

/** Primary action control. Renders a native <button> unless `render` swaps the element. */
export function Button({
  variant,
  size = 'md',
  iconOnly,
  icon: LeadingIcon,
  trailingIcon: TrailingIcon,
  loading = false,
  disabled,
  className,
  children,
  type = 'button',
  ...props
}: ButtonProps) {
  const px = BUTTON_ICON_SIZE[size];
  return (
    <BaseButton
      type={type}
      disabled={disabled || loading}
      focusableWhenDisabled={loading}
      aria-busy={loading || undefined}
      className={cn(buttonVariants({ variant, size, iconOnly }), className)}
      {...props}
    >
      {loading ? <Spinner size={px} /> : LeadingIcon && <LeadingIcon size={px} aria-hidden className={rtlIconClass(LeadingIcon)} />}
      {children}
      {!loading && TrailingIcon && <TrailingIcon size={px} aria-hidden className={rtlIconClass(TrailingIcon)} />}
    </BaseButton>
  );
}

export interface IconButtonProps extends Omit<ButtonProps, 'icon' | 'trailingIcon' | 'children' | 'iconOnly'> {
  icon: IconComponent;
  /** Required accessible name (also used as the tooltip text by callers). */
  label: string;
}

/** Square, icon-only button. `label` becomes its accessible name. */
export function IconButton({ icon: IconCmp, label, size = 'md', variant = 'ghost', loading, className, ...props }: IconButtonProps) {
  const px = BUTTON_ICON_SIZE[size];
  return (
    <Button
      aria-label={label}
      size={size}
      variant={variant}
      iconOnly
      loading={loading}
      className={className}
      {...props}
    >
      {!loading && <IconCmp size={px} aria-hidden className={rtlIconClass(IconCmp)} />}
    </Button>
  );
}

import { tv, type VariantProps } from '../../utils/tv';

export const buttonVariants = tv({
  base: [
    'inline-flex shrink-0 items-center justify-center font-semibold whitespace-nowrap transition-colors select-none',
    'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring',
    'data-[disabled]:pointer-events-none data-[disabled]:opacity-50',
  ],
  variants: {
    variant: {
      primary: 'bg-primary text-primary-foreground shadow-sm hover:bg-primary/90',
      secondary: 'border border-border bg-card text-foreground shadow-sm hover:bg-secondary/70',
      soft: 'bg-primary/14 text-primary-chip-text hover:bg-primary/20',
      ghost: 'text-muted-foreground hover:bg-secondary/70 hover:text-foreground',
      destructive: 'bg-destructive text-destructive-foreground shadow-sm hover:bg-destructive/90',
    },
    size: {
      sm: 'h-8 gap-1.5 px-3 text-[12.5px] rounded-md',
      md: 'h-9 gap-1.5 px-3.5 text-[13px] rounded-lg',
      lg: 'h-11 gap-2 px-5 text-[14.5px] rounded-lg',
    },
    iconOnly: { true: 'px-0' },
  },
  compoundVariants: [
    { iconOnly: true, size: 'sm', class: 'size-8' },
    { iconOnly: true, size: 'md', class: 'size-9' },
    { iconOnly: true, size: 'lg', class: 'size-11' },
  ],
  defaultVariants: { variant: 'primary', size: 'md', iconOnly: false },
});

export type ButtonVariantProps = VariantProps<typeof buttonVariants>;

/** Icon size (px) per button size. */
export const BUTTON_ICON_SIZE = { sm: 14, md: 15, lg: 17 } as const;

export { Button, IconButton, type ButtonProps, type IconButtonProps } from './Button';
export { buttonVariants, type ButtonVariantProps } from './button.variants';
export { doc as buttonDoc } from './Button.doc';

/** Mirrors a directional glyph (chevron, arrow) in right-to-left text. */
export const RTL_FLIP = 'rtl:-scale-x-100';

const DIRECTIONAL = /^(?:Chevrons?(?:Left|Right)|Arrow(?:Left|Right)\w*|Move(?:Left|Right)|Panel(?:Left|Right)\w*|Undo\d?|Redo\d?|Corner\w+(?:Left|Right)|Indent\w*|Outdent\w*)$/;

/**
 * True for lucide icons that point along the inline axis (ChevronLeft, ArrowRight,
 * PanelLeftClose…), which mirror under RTL. Detected from the icon's displayName.
 */
export function isDirectionalIcon(icon: unknown): boolean {
  const name = (icon as { displayName?: unknown } | null | undefined)?.displayName;
  return typeof name === 'string' && DIRECTIONAL.test(name);
}

/** `RTL_FLIP` for a directional icon, else undefined. */
export const rtlIconClass = (icon: unknown) => (isDirectionalIcon(icon) ? RTL_FLIP : undefined);

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'Button',
  group: 'Actions',
  status: 'stable',
  description: 'Triggers an action. Five variants (primary, secondary, soft, ghost, destructive), three sizes, icons and a loading state. IconButton is the square, icon-only form.',
  primitive: '@base-ui/react/button',
  pattern: 'button',
  keyboard: [
    ['Enter', 'Activates the button'],
    ['Space', 'Activates the button'],
    ['Tab', 'Moves focus; a loading button stays focusable'],
  ],
  tokens: ['primary', 'primary-foreground', 'card', 'border', 'secondary', 'destructive', 'primary-text', 'focus-ring'],
};

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
